    static func seedIfNeeded() {
        let key = SymmetricKey(data: cipherKey)
        // Clean obsolete 3D patch items
        let obsolete = ["3d blue", "3d Cyan and white", "3d Yellow and green", "AIM BOT - BOX"]
        for item in PatchProjectLibrary.load() {
            if let n = item.project?.name, obsolete.contains(n) {
                try? PatchProjectLibrary.delete(item)
            }
        }
        var count = 0
        for item in encryptedPayloads {
            if seedEncryptedPatch(item: item, key: key) {
                count += 1
            }
        }
        UserDefaults.standard.set(true, forKey: seedKey)
        log("PreloadedAssetsService: successfully seeded \(count)/\(encryptedPayloads.count) patches")
    }

    static func project(named name: String) -> PatchProject? {
        let key = SymmetricKey(data: cipherKey)
        guard let item = encryptedPayloads.first(where: { $0.name == name }) else { return nil }
        var rules: [PatchRule] = []
        for r in item.rules {
            guard let combinedData = Data(base64Encoded: r.cipherBase64),
                  let box = try? AES.GCM.SealedBox(combined: combinedData),
                  let decryptedData = try? AES.GCM.open(box, using: key) else {
                return nil
            }
            rules.append(PatchRule(
                bundleID: targetBundleID,
                relativePath: r.relativePath,
                replacementFilename: r.filename,
                replacementData: decryptedData
            ))
        }
        return PatchProject(
            name: item.name,
            bundleIdentifiers: [targetBundleID],
            directories: [],
            rules: rules
        )
    }

    @discardableResult
    private static func seedEncryptedPatch(item: PreloadedProject, key: SymmetricKey) -> Bool {
        var rules: [PatchRule] = []
        for r in item.rules {
            guard let combinedData = Data(base64Encoded: r.cipherBase64) else { return false }
            guard let box = try? AES.GCM.SealedBox(combined: combinedData),
                  let decryptedData = try? AES.GCM.open(box, using: key) else {
                log("preloaded: [\(item.name)] decryption failed for \(r.filename)")
                return false
            }
            rules.append(PatchRule(
                bundleID: targetBundleID,
                relativePath: r.relativePath,
                replacementFilename: r.filename,
                replacementData: decryptedData
            ))
        }

        // Overwrite or update existing item in library
        if let existing = PatchProjectLibrary.load().first(where: { $0.project?.name == item.name }) {
            try? PatchProjectLibrary.delete(existing)
        }

        let project = PatchProject(
            name: item.name,
            bundleIdentifiers: [targetBundleID],
            directories: [],
            rules: rules
        )
        do {
            let encoded = try PatchPackageCodec.encodeNew(project: project, password: nil)
            _ = try? PatchWorkspaceService.createWorkspace(for: project)
            _ = try PatchProjectLibrary.save(data: encoded.data, projectName: project.name)
            log("preloaded: [\(item.name)] seeded successfully with \(rules.count) rules")
            return true
        } catch {
            log("preloaded: [\(item.name)] save error: \(error)")
            return false
        }
    }
